def transform(grid):
    if not grid:
        return grid
    result = []
    for row in grid:
        if not row:
            result.append(row)
            continue
        first_pixel = row[0]
        new_row = []
        for pixel in row:
            if pixel == first_pixel:
                new_row.append(pixel)
            else:
                new_row.append(1)
        result.append(new_row)
    return result
